def read(p):
 with p.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def write(p,fields,rows):
 with p.open('w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
def main():
 root=Path(__file__).resolve().parents[1]; proc=root/'data/processed/v0.1.0-preview'; meta=root/'metadata'; src=read(root/'data/source_records/source_records.csv'); srcids={x['source_record_id']:x for x in src};
