 lineage=[]; inventory=[]; cov=[]
 for fn in CSV_FILES:
  rs=read(proc/fn); fields=list(rs[0]) if rs else []; key=next((k for k in ('market_id','dc_id','supplier_id','node_id') if k in fields),'record')
